DROP TABLE IF EXISTS `lessons`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lessons` (
  `Id` char(36) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL,
  `ModuleId` char(36) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL,
  `SubTopic` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `Activity` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `VideoUrl` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `DiagramUrl` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `Code` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `Procedure` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `CreatedByTeacherId` char(36) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL,
  `IsActive` tinyint(1) NOT NULL DEFAULT '1',
  `CreatedAt` datetime(6) NOT NULL,
  `RequiredMaterial` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `WhatYouGet` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `SerialNumber` int NOT NULL DEFAULT '0',
  `TotalHours` int NOT NULL DEFAULT '0',
  `EndPage` int DEFAULT NULL,
  `StartPage` int DEFAULT NULL,
  `IsActivity` tinyint(1) NOT NULL DEFAULT '0',
  `IsDeleted` tinyint(1) NOT NULL,
  `DeletedDate` datetime(6) DEFAULT NULL,
  `DeletedBy` char(36) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL,
  `Source` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `IsRoboticsActivity` tinyint(1) NOT NULL DEFAULT '0',
  `IsPythonActivity` tinyint(1) NOT NULL DEFAULT '0',
  `IsAiToolActivity` tinyint(1) NOT NULL DEFAULT '0',
  `BrowserUrl` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `PdfFileUrl` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `UpdatedDate` datetime(6) DEFAULT NULL,
  `UpdatedBy` char(36) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL,
  `CreatedBy` char(36) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL,
  `ExpectedPeriods` int NOT NULL DEFAULT '1',
  `VideoUrls` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `DisplayOrder` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`Id`),
  KEY `IX_lessons_CreatedByTeacherId` (`CreatedByTeacherId`),
  KEY `IX_lessons_module` (`ModuleId`),
  KEY `IX_lessons_module_active` (`ModuleId`,`IsActive`),
  KEY `IX_lessons_IsDeleted` (`IsDeleted`),
  CONSTRAINT `FK_lessons_modules_ModuleId` FOREIGN KEY (`ModuleId`) REFERENCES `modules` (`Id`) ON DELETE CASCADE,
  CONSTRAINT `FK_lessons_teachers_CreatedByTeacherId` FOREIGN KEY (`CreatedByTeacherId`) REFERENCES `teachers` (`Id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
